"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import type { DiaxRelation } from "diax";
import {
  Cloud,
  Database,
  FileCode2,
  Globe2,
  Monitor,
  Server,
  ShieldCheck,
  Smartphone,
  Users,
} from "lucide-react";
import type { ReactNode } from "react";

const targets = {
  externalUser: "user-external",
  internalUser: "user-internal",
  mobileUser: "user-mobile",
  frontend: "frontend-layer",
  article: "article-detail",
  backend: "backend-layer",
  mysql: "storage-mysql",
  cdn: "storage-cdn",
  account: "service-account",
} as const;

const relations = [
  relation("external-to-frontend", targets.externalUser, targets.frontend, "#38758a", "HTTPS"),
  relation("internal-to-frontend", targets.internalUser, targets.frontend, "#6d5ba7", "HTTPS"),
  relation("mobile-to-article", targets.mobileUser, targets.article, "#3567b7", "deep link"),
  relation("frontend-to-backend", targets.frontend, targets.backend, "#3567b7", "JSON / HTTPS"),
  relation("backend-to-mysql", targets.backend, targets.mysql, "#6d5ba7", "SQL"),
  relation("backend-to-cdn", targets.backend, targets.cdn, "#6d5ba7", "object write"),
  relation("backend-to-account", targets.backend, targets.account, "#6d5ba7", "gRPC"),
] as const satisfies readonly DiaxRelation<ReactNode>[];

function relation(
  id: string,
  from: string,
  to: string,
  color: string,
  label: string,
): DiaxRelation<ReactNode> {
  return {
    id,
    from,
    to,
    color,
    label: <ProtocolLabel>{label}</ProtocolLabel>,
    targetMarker: "arrow",
    gap: 5,
  };
}

const actors = [
  { id: targets.externalUser, title: "External user", detail: "Public access", icon: Globe2 },
  { id: targets.internalUser, title: "Operations", detail: "Managed publish", icon: Users },
  { id: targets.mobileUser, title: "Mobile reader", detail: "Article view", icon: Smartphone },
] as const;

const storage = [
  { id: targets.mysql, title: "MySQL", detail: "Content & metadata", icon: Database },
  { id: targets.cdn, title: "Dual-bucket CDN", detail: "HTML & static assets", icon: Cloud },
  { id: targets.account, title: "Account gRPC", detail: "Identity & access", icon: Users },
] as const;

const endpointClass =
  "relative min-w-0 border border-slate-300 bg-white text-slate-900 shadow-[0_8px_22px_rgb(42_56_72_/_0.09)]";

export default function DomSystemArchitecture() {
  return (
    <figure
      data-showcase-corpus="dom-system-architecture"
      className="w-full max-w-[1120px] overflow-hidden rounded-xl border border-slate-300 bg-[#e8eef1] p-3 text-slate-900 shadow-[0_24px_70px_rgb(31_47_60_/_0.16)] sm:p-6"
    >
      <figcaption className="mb-5 flex flex-col justify-between gap-3 border-b border-slate-300 pb-4 sm:flex-row sm:items-end">
        <div>
          <p className="m-0 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-[#2d7188]">
            Real DOM architecture map
          </p>
          <h2 className="m-0 mt-1 text-xl font-semibold tracking-[-0.035em] sm:text-3xl">
            Content delivery system
          </h2>
          <p className="m-0 mt-1 text-[10px] leading-relaxed text-slate-600 sm:text-xs">
            Authored CSS owns the layers. DiaX keeps 7 relationships attached as the page reflows.
          </p>
        </div>
        <dl className="m-0 flex gap-4 font-mono text-[8px] text-slate-600">
          <div>
            <dt>Targets</dt>
            <dd className="m-0 mt-0.5 text-base font-semibold text-slate-900">9</dd>
          </div>
          <div>
            <dt>Relations</dt>
            <dd className="m-0 mt-0.5 text-base font-semibold text-slate-900">7</dd>
          </div>
          <div>
            <dt>Anchors</dt>
            <dd className="m-0 mt-0.5 text-base font-semibold text-slate-900">0</dd>
          </div>
        </dl>
      </figcaption>

      <ProtocolLegend />

      <ConnectionSurface
        relations={relations}
        aria-label="Content delivery system relationships"
        className="grid gap-14 overflow-hidden rounded-lg border border-slate-300 bg-[#f5f7f8] p-3 pb-14 [background-image:linear-gradient(rgb(48_71_88_/_0.05)_1px,transparent_1px),linear-gradient(90deg,rgb(48_71_88_/_0.05)_1px,transparent_1px)] [background-size:24px_24px] sm:gap-16 sm:p-6 sm:pb-16"
      >
        <section aria-labelledby="audience-title">
          <BandHeading index="00" eyebrow="Entry points" title="Audience" id="audience-title" />
          <div className="mx-auto mt-3 grid max-w-2xl grid-cols-3 gap-2 sm:gap-5">
            {actors.map(({ id, title, detail, icon: Icon }) => (
              <article
                key={id}
                {...connectionTarget(id)}
                className={`${endpointClass} flex min-h-12 items-center justify-center gap-1 rounded-full px-1.5 py-2 text-center sm:gap-2 sm:px-3`}
              >
                <Icon
                  aria-hidden="true"
                  className="hidden size-3.5 shrink-0 text-[#2d7188] sm:block"
                />
                <span className="min-w-0">
                  <strong className="block truncate text-[8px] sm:text-[11px]">{title}</strong>
                  <small className="mt-0.5 block truncate text-[6px] text-slate-500 sm:text-[8px]">
                    {detail}
                  </small>
                </span>
              </article>
            ))}
          </div>
        </section>

        <Layer
          id={targets.frontend}
          labelId="frontend-title"
          index="01"
          eyebrow="Presentation"
          title="Frontend applications"
          icon={Monitor}
          tone="blue"
        >
          <AppCard
            icon={FileCode2}
            title="Publishing console"
            detail="Upload · preview · release"
            code="React"
          />
          <AppCard
            id={targets.article}
            icon={Monitor}
            title="Article detail"
            detail="Content · comments · sharing"
            code="React"
          />
          <AppCard
            icon={Smartphone}
            title="App handoff"
            detail="Open the native app"
            code="DOM script"
          />
        </Layer>

        <Layer
          id={targets.backend}
          labelId="backend-title"
          index="02"
          eyebrow="Application"
          title="Publishing service"
          icon={Server}
          tone="violet"
        >
          <ApiCard title="Public API" auth="Cookie auth" path="/x/article/content" />
          <ApiCard title="Operations API" auth="Permit auth" path="/api/content" />
        </Layer>

        <section
          className="relative rounded-lg border border-amber-700/30 bg-amber-50/60 p-2.5 sm:p-4"
          aria-labelledby="storage-title"
        >
          <BandHeading
            index="03"
            eyebrow="Infrastructure"
            title="Storage & dependencies"
            id="storage-title"
          />
          <div className="mx-auto mt-3 grid max-w-2xl grid-cols-3 gap-1.5 sm:gap-3">
            {storage.map(({ id, title, detail, icon: Icon }) => (
              <article
                key={id}
                {...connectionTarget(id)}
                className={`${endpointClass} rounded-md p-1.5 text-center sm:p-3`}
              >
                <Icon aria-hidden="true" className="mx-auto size-3 text-amber-700 sm:size-4" />
                <h3 className="m-0 mt-1 truncate text-[7px] font-semibold sm:text-[10px]">
                  {title}
                </h3>
                <p className="m-0 mt-1 line-clamp-2 text-[5px] leading-snug text-slate-500 sm:text-[8px]">
                  {detail}
                </p>
              </article>
            ))}
          </div>
        </section>
      </ConnectionSurface>
    </figure>
  );
}

function ProtocolLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-slate-300 bg-[#f5f7f8] px-1.5 py-0.5 font-mono text-[7px] font-bold text-slate-600 sm:text-[9px]">
      {children}
    </span>
  );
}

function ProtocolLegend() {
  return (
    <dl
      aria-label="Architecture protocol legend"
      className="m-0 mb-4 grid border-y border-slate-300 text-[8px] text-slate-600 sm:grid-cols-3"
    >
      <ProtocolFact term="Web boundary" value="HTTPS · deep link" />
      <ProtocolFact term="Service boundary" value="JSON / HTTPS · gRPC" />
      <ProtocolFact term="Durable boundary" value="SQL · object write" />
    </dl>
  );
}

function ProtocolFact({ term, value }: { term: string; value: string }) {
  return (
    <div className="grid grid-cols-[auto_minmax(0,1fr)] gap-2 px-3 py-2 sm:border-l sm:first:border-l-0">
      <dt className="font-mono font-bold uppercase tracking-[0.08em] text-[#2d7188]">{term}</dt>
      <dd className="m-0 text-right">{value}</dd>
    </div>
  );
}

function BandHeading({
  index,
  eyebrow,
  title,
  id,
}: {
  index: string;
  eyebrow: string;
  title: string;
  id: string;
}) {
  return (
    <div className="relative z-10 grid grid-cols-[28px_minmax(0,1fr)] items-center gap-2 sm:grid-cols-[32px_minmax(0,1fr)]">
      <span className="grid size-7 place-items-center rounded-md border border-slate-300 bg-white font-mono text-[8px] font-bold text-slate-500 sm:size-8">
        {index}
      </span>
      <div>
        <p className="m-0 font-mono text-[6px] font-bold uppercase tracking-[0.12em] text-slate-500 sm:text-[8px]">
          {eyebrow}
        </p>
        <h2 id={id} className="m-0 mt-0.5 text-[11px] font-semibold sm:text-sm">
          {title}
        </h2>
      </div>
    </div>
  );
}

function Layer({
  id,
  labelId,
  index,
  eyebrow,
  title,
  icon: Icon,
  tone,
  children,
}: {
  id: string;
  labelId: string;
  index: string;
  eyebrow: string;
  title: string;
  icon: typeof Monitor;
  tone: "blue" | "violet";
  children: React.ReactNode;
}) {
  const toneClass =
    tone === "blue" ? "border-blue-700/25 bg-blue-50/55" : "border-violet-700/25 bg-violet-50/55";
  return (
    <section
      {...connectionTarget(id)}
      className={`relative rounded-lg border p-2.5 sm:p-4 ${toneClass}`}
      aria-labelledby={labelId}
    >
      <div className="grid grid-cols-[28px_minmax(0,1fr)] items-center gap-2 sm:grid-cols-[32px_minmax(0,1fr)]">
        <span className="grid size-7 place-items-center rounded-md border border-current bg-white text-slate-500 sm:size-8">
          <Icon aria-hidden="true" className="size-3.5" />
        </span>
        <div>
          <p className="m-0 font-mono text-[6px] font-bold uppercase tracking-[0.12em] text-slate-500 sm:text-[8px]">
            {index} · {eyebrow}
          </p>
          <h2 id={labelId} className="m-0 mt-0.5 text-[11px] font-semibold sm:text-sm">
            {title}
          </h2>
        </div>
      </div>
      <div className="mt-3 grid grid-cols-3 gap-1.5 sm:gap-3">{children}</div>
    </section>
  );
}

function AppCard({
  id,
  icon: Icon,
  title,
  detail,
  code,
}: {
  id?: string;
  icon: typeof Monitor;
  title: string;
  detail: string;
  code: string;
}) {
  return (
    <article
      {...(id ? connectionTarget(id) : {})}
      className={`${endpointClass} rounded-md p-1.5 sm:p-3`}
    >
      <Icon aria-hidden="true" className="size-3 text-blue-700 sm:size-4" />
      <h3 className="m-0 mt-1 truncate text-[7px] font-semibold sm:text-[10px]">{title}</h3>
      <p className="m-0 mt-1 line-clamp-2 text-[5px] leading-snug text-slate-500 sm:text-[8px]">
        {detail}
      </p>
      <code className="mt-1 inline-block rounded bg-blue-50 px-1 py-0.5 text-[5px] text-blue-700 sm:text-[7px]">
        {code}
      </code>
    </article>
  );
}

function ApiCard({ title, auth, path }: { title: string; auth: string; path: string }) {
  return (
    <article className={`${endpointClass} col-span-3 rounded-md p-2 sm:col-span-1 sm:p-3`}>
      <div className="flex items-center gap-1.5">
        <ShieldCheck aria-hidden="true" className="size-3 text-violet-700" />
        <h3 className="m-0 text-[8px] font-semibold sm:text-[10px]">{title}</h3>
      </div>
      <code className="mt-1 block truncate text-[6px] text-violet-700 sm:text-[8px]">{path}</code>
      <p className="m-0 mt-1 text-[6px] text-slate-500 sm:text-[8px]">{auth}</p>
    </article>
  );
}
